<script setup lang="ts">
import {computed,ref} from 'vue';
import {useMcpChecks,mcpCheckKey} from '../composables/useMcpChecks';
import type {McpServer} from '../api/mcp';
const props=defineProps<{server:McpServer;disabled?:boolean;expanded?:boolean}>();
const {checks,check,cancel}=useMcpChecks();const open=ref(false);
const current=computed(()=>checks[mcpCheckKey(props.server)]);
const working=computed(()=>['checking','queued'].includes(current.value?.state||''));
const text=computed(()=>props.disabled?'未检测（已暂停）':current.value?.state==='queued'?'等待检测':working.value?'正在连接并发现工具…':current.value?.result?.message||'尚未检测');
const when=computed(()=>current.value?.result?new Date(current.value.result.checked_at*1000).toLocaleTimeString('zh-CN',{hour12:false}):'');
const phaseNames:Record<string,string>={prepare:'配置与环境',connect:'连接 / 启动进程',initialize:'MCP 握手',tools:'发现工具',complete:'检测完成'};
</script>
<template>
 <div class="mcp-check" :class="[disabled?'paused':current?.state,{expanded}]">
  <button class="check-message" :disabled="!current?.result" :title="text" @click="open=true"><i :class="{spin:working}"/>{{text}}</button>
  <button v-if="!working" class="check-action" :disabled="disabled" @click="check(server)">{{current?.result?'重新检测':expanded?'立即检测':'检测'}}</button><button v-else class="check-action" @click="cancel(server)">停止</button>
  <span v-if="expanded&&when" class="check-time">{{when}} · {{current?.result?.elapsed_ms}} ms</span>
 </div>
 <Teleport to="body"><div v-if="open" class="check-mask" @click.self="open=false"><section class="check-dialog" role="dialog" aria-modal="true" aria-label="MCP 检测结果"><header><div><h2>{{server.name}} · 检测结果</h2><p>{{current?.result?.message}}</p></div><button aria-label="关闭检测结果" @click="open=false">×</button></header><div class="check-body"><dl><dt>检测阶段</dt><dd>{{phaseNames[current?.result?.phase||'']||current?.result?.phase}}</dd><dt>检测时间</dt><dd>{{when}} · {{current?.result?.elapsed_ms}} ms</dd><dt v-if="current?.result?.protocol">协议版本</dt><dd v-if="current?.result?.protocol">{{current.result.protocol}}</dd><dt v-if="current?.result?.server_name">服务</dt><dd v-if="current?.result?.server_name">{{current.result.server_name}} {{current.result.server_version}}</dd></dl><p v-if="current?.result?.details" class="check-error">{{current.result.details}}</p><p class="check-note">检测仅检查连接、握手与工具发现，不调用业务工具。目标 Agent 仍可能需要独立信任或 OAuth；具体工具权限需在实际调用时验证。</p><h3 v-if="current?.result?.tool_count">已发现 {{current.result.tool_count}}{{current.result.partial?'+':''}} 个工具</h3><article v-for="tool in current?.result?.tools" :key="tool.name"><b>{{tool.name}}</b><p>{{tool.description}}</p></article><p v-if="(current?.result?.tool_count||0)>200" class="check-note">这里只预览前 200 个工具。</p></div><footer><button class="btn" @click="open=false">关闭</button><button class="btn primary" :disabled="working||disabled" @click="check(server)">重新检测</button></footer></section></div></Teleport>
</template>
<style scoped>
.mcp-check{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:9px;max-width:100%;font-size:9px}.check-message{display:flex;align-items:center;gap:6px;min-width:0;max-width:100%;background:none;border:0;padding:0;color:var(--faint);font-size:inherit;cursor:pointer;text-align:left;overflow-wrap:anywhere}.check-message:disabled{opacity:1;cursor:default}.check-message i{width:5px;height:5px;flex-shrink:0;border-radius:50%;background:var(--border)}.ok .check-message{color:var(--green)}.ok .check-message i{background:var(--green)}.failed .check-message{color:var(--red)}.failed .check-message i{background:var(--red)}.auth_required .check-message,.connected .check-message{color:var(--amber)}.auth_required i,.connected i{background:var(--amber)}.mcp-check:not(.expanded) .check-message{display:block;max-width:255px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mcp-check:not(.expanded) .check-message i{display:inline-block;margin-right:6px}.check-action{background:none;border:0;padding:0;font-size:inherit;color:var(--accent);cursor:pointer;white-space:nowrap}.check-action:disabled{opacity:.45;cursor:not-allowed}.spin{border:1px solid var(--border);border-top-color:var(--accent);width:10px!important;height:10px!important;background:none!important;animation:spin .8s linear infinite}.expanded{font-size:11px;padding:13px 14px;border:1px solid var(--border);border-radius:8px;background:var(--bg-soft)}.check-time{font-size:10px;color:var(--faint);margin-left:auto}.check-mask{position:fixed;inset:0;z-index:160;background:#0005;backdrop-filter:blur(3px);display:flex;align-items:center;justify-content:center;padding:24px}.check-dialog{width:680px;max-width:100%;max-height:85vh;display:flex;flex-direction:column;background:var(--panel);color:var(--text);border:1px solid var(--border);border-radius:13px;box-shadow:0 24px 80px #0002}header{padding:22px 25px;display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid var(--border)}header h2{font-size:18px;margin:0 0 10px}header p{font-size:12px;color:var(--muted);line-height:1.7;margin:0}header>button{align-self:start;background:none;border:0;font-size:23px;color:var(--muted);cursor:pointer}.check-body{overflow:auto;padding:18px 25px}dl{display:grid;grid-template-columns:85px 1fr;font-size:11px;gap:12px;margin:0 0 18px}dt{color:var(--faint)}dd{margin:0;overflow-wrap:anywhere}.check-note{font-size:10px;line-height:1.8;color:var(--muted)}.check-error{font:11px/1.8 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--red-soft);color:var(--red);padding:12px;border-radius:7px}h3{font-size:12px;margin:24px 0 8px}article{border-bottom:1px solid var(--border-soft);padding:12px 0}article b{font:11px Consolas,monospace;overflow-wrap:anywhere}article p{font-size:10px;color:var(--muted);line-height:1.7;margin:7px 0 0;overflow-wrap:anywhere}footer{display:flex;justify-content:flex-end;gap:10px;padding:16px 25px;border-top:1px solid var(--border)}@keyframes spin{to{transform:rotate(360deg)}}
</style>
